3	/**
4	 * Derives an owner's locality (region) from the city using a fixed city-to-region table.
5	 *
6	 * <p>Kept as a standalone helper rather than a method on {@link OwnerMapper}: a single-argument
7	 * {@code String}-to-{@code String} method declared on a MapStruct mapper would be picked up as an
8	 * implicit conversion and applied to every String property mapping.
9	 */
10	final class OwnerLocality {
11	
12	    private OwnerLocality() {
13	    }
14	
15	    /**
16	     * Returns the canonical region for {@code city} (Sydney-&gt;NSW, Melbourne-&gt;VIC,
17	     * Brisbane-&gt;QLD), or {@code "UNKNOWN"} when the city is not in the table.
18	     */
19	    static String derive(String city) {
20	        if (city == null) {
21	            return "UNKNOWN";
22	        }
23	        switch (city) {
24	            case "Sydney":
25	                return "NSW";
26	            case "Melbourne":
27	                return "VIC";
28	            case "Brisbane":
29	                return "QLD";
30	            default:
31	                return "UNKNOWN";
32	        }
33	    }
34	}
