288	    /**
289	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
290	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
291	     * does not catch). The names of all offending fields are collected so the caller receives a
292	     * 400 response whose {@code errors} array lists each one.
293	     */
294	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
295	        List<String> missingFields = new ArrayList<>();
296	        if (isBlank(ownerFieldsDto.getFirstName())) {
297	            missingFields.add("firstName");
298	        }
299	        if (isBlank(ownerFieldsDto.getLastName())) {
300	            missingFields.add("lastName");
301	        }
302	        if (isBlank(ownerFieldsDto.getAddress())) {
303	            missingFields.add("address");
304	        }
305	        if (isBlank(ownerFieldsDto.getCity())) {
306	            missingFields.add("city");
307	        }
308	        if (isBlank(ownerFieldsDto.getTelephone())) {
309	            missingFields.add("telephone");
310	        }
311	        if (!missingFields.isEmpty()) {
312	            throw new InvalidOwnerFieldsException(missingFields);
313	        }
314	    }
