320	    /**
321	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
322	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
323	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
324	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
325	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
326	     * means an address that is blank after normalization is rejected like a missing one.
327	     */
328	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
329	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
330	    }
331	
332	    /**
333	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
334	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
335	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
336	     * address is returned unchanged, making it safe to apply to stored values during comparison.
337	     */
338	    private static String canonicalAddress(String address) {
339	        if (address == null) {
340	            return null;
341	        }
342	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
343	        if (collapsed.isEmpty()) {
344	            return "";
345	        }
346	        String[] tokens = collapsed.split(" ");
347	        StringBuilder sb = new StringBuilder(collapsed.length());
348	        for (int i = 0; i < tokens.length; i++) {
349	            if (i > 0) {
350	                sb.append(' ');
351	            }
352	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
353	        }
354	        return sb.toString();
355	    }
