357	    /**
358	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
359	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
360	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
361	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
362	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
363	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
364	     * written back onto the request so it is what gets stored and returned. Any value that cannot
365	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
366	     * {@code telephone}.
367	     */
368	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
369	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
370	    }
371	
372	    /**
373	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
374	     * (400) naming {@code telephone} when it cannot form a valid number.
375	     */
376	    private static String toE164(String telephone) {
377	        if (telephone == null) {
378	            throw new InvalidOwnerFieldsException(List.of("telephone"));
379	        }
380	        boolean hasCountryCode = telephone.trim().startsWith("+");
381	        String digits = telephone.replaceAll("\\D", "");
382	        String countryCode;
383	        String national;
384	        if (hasCountryCode) {
385	            countryCode = matchCountryCode(digits);
386	            national = digits;
387	        } else {
388	            countryCode = "61";
389	            if (digits.startsWith("0")) {
390	                digits = digits.substring(1);
391	            }
392	            national = "61" + digits;
393	        }
394	        if (!national.matches("[0-9]{8,15}")) {
395	            throw new InvalidOwnerFieldsException(List.of("telephone"));
396	        }
397	        if (countryCode != null) {
398	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
399	            if (requiredLength != null
400	                && national.length() - countryCode.length() != requiredLength) {
401	                throw new InvalidOwnerFieldsException(List.of("telephone"));
402	            }
403	        }
404	        return "+" + national;
405	    }
406	
407	    /**
408	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
409	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
410	     * the number is not length-checked against a country.
411	     */
412	    private static String matchCountryCode(String digits) {
413	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
414	            .filter(digits::startsWith)
415	            .max(Comparator.comparingInt(String::length))
416	            .orElse(null);
417	    }
