419	    /**
420	     * Rejects creating an owner whose derived {@code identityKey} already, in its entirety, belongs
421	     * to another owner. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' +
422	     * (householdId or empty)}, so it folds the former separate telephone, email and household
423	     * duplicate checks into one: only an exact full-key match is a duplicate. In particular two
424	     * members of the same household (same {@code householdId}) with different telephones have
425	     * different keys and are both allowed. The incoming telephone and email have already been
426	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}, and the household id has
427	     * been resolved by {@link #resolveHouseholdId}; each existing owner's key is derived the same way
428	     * before comparison. A match results in a 409 response naming {@code identityKey}.
429	     */
430	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
431	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
432	        for (Owner existing : this.clinicService.findAllOwners()) {
433	            if (identityKey.equals(existingIdentityKey(existing))) {
434	                throw new DuplicateOwnerIdentityException(identityKey);
435	            }
436	        }
437	    }
438	
439	    /**
440	     * Builds an {@code identityKey} from its three parts: {@code telephone + '|' + email + '|' +
441	     * householdId}, with a {@code null} part contributing the empty string. The telephone and email
442	     * are expected to already be in their normalized (E.164, lower-cased) forms.
443	     */
444	    private static String identityKey(String telephone, String email, String householdId) {
445	        return orEmpty(telephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
446	    }
447	
448	    /**
449	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
450	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
451	     * the stored email is lower-cased, and the stored household id is used as-is.
452	     */
453	    private static String existingIdentityKey(Owner existing) {
454	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
455	        String email = existing.getEmail() == null ? "" : existing.getEmail().toLowerCase(Locale.ROOT);
456	        return identityKey(telephone, email, existing.getHouseholdId());
457	    }
458	
459	    private static String orEmpty(String value) {
460	        return value == null ? "" : value;
461	    }
462	
463	    /**
464	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
465	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
466	     */
467	    private static String normalizeExisting(String telephone) {
468	        try {
469	            return toE164(telephone);
470	        } catch (InvalidOwnerFieldsException ex) {
471	            return null;
472	        }
473	    }
