475	    /**
476	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
477	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
478	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
479	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
480	     */
481	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
482	        String city = ownerFieldsDto.getCity();
483	        int count = 0;
484	        for (Owner existing : this.clinicService.findAllOwners()) {
485	            if (city.equalsIgnoreCase(existing.getCity())) {
486	                count++;
487	            }
488	        }
489	        if (count >= MAX_OWNERS_PER_CITY) {
490	            throw new OwnerCityAtCapacityException(city);
491	        }
492	    }
