494	    /**
495	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
496	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
497	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
498	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
499	     */
500	    private void rejectDailyLimitReached(LocalDate registrationDate) {
501	        int count = 0;
502	        for (Owner existing : this.clinicService.findAllOwners()) {
503	            if (registrationDate.equals(existing.getRegistrationDate())) {
504	                count++;
505	            }
506	        }
507	        if (count >= MAX_OWNERS_PER_DAY) {
508	            throw new DailyOwnerLimitReachedException(registrationDate);
509	        }
510	    }
