512	    /**
513	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
514	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
515	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
516	     */
517	    private static String normalizeForComparison(String value) {
518	        if (value == null) {
519	            return "";
520	        }
521	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
522	    }
