524	    /**
525	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
526	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
527	     * written back onto the request so that is what gets stored and returned. A present but invalid
528	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
529	     */
530	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
531	        String email = ownerFieldsDto.getEmail();
532	        if (email == null) {
533	            return;
534	        }
535	        String trimmed = email.trim();
536	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
537	            throw new InvalidOwnerFieldsException(List.of("email"));
538	        }
539	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
540	    }
541	
542	    /**
543	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
544	     * day. When the caller supplies no value it defaults to the server's current date; a value
545	     * provided in the request is kept. The effective date, whether supplied or defaulted, must fall
546	     * on a business day: a Saturday or Sunday is rolled forward to the following Monday. The adjusted
547	     * date is written back onto the request so it is what gets stored and returned (in ISO
548	     * {@code YYYY-MM-DD} format) and what every value derived from the registration date is based on.
549	     */
550	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
551	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
552	        if (effective == null) {
553	            effective = LocalDate.now();
554	        }
555	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
556	    }
557	
558	    /**
559	     * Rolls a date forward onto a business day: a Saturday or Sunday is advanced to the following
560	     * Monday; a weekday is returned unchanged.
561	     */
562	    private static LocalDate toBusinessDay(LocalDate date) {
563	        return switch (date.getDayOfWeek()) {
564	            case SATURDAY -> date.plusDays(2);
565	            case SUNDAY -> date.plusDays(1);
566	            default -> date;
567	        };
568	    }
569	
570	    /**
571	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
572	     * where {@code CITY3} is the upper-cased first three letters of {@code city}, {@code LAST3} is the
573	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a per-city 4-digit
574	     * zero-padded sequence equal to one more than the number of owners already in that city
575	     * (e.g. {@code 'SYD-SMI-0007'}).
576	     */
577	    private void assignCustomerCode(Owner owner) {
578	        String city = owner.getCity();
579	        String lastName = owner.getLastName();
580	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
581	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
582	        int sequence = 1;
583	        for (Owner existing : this.clinicService.findAllOwners()) {
584	            if (city.equalsIgnoreCase(existing.getCity())) {
585	                sequence++;
586	            }
587	        }
588	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
589	    }
