591	    /**
592	     * Assigns the owner's {@code membershipNumber} on create, formatted
593	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
594	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}). Assigned after
595	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
596	     * inputs are present.
597	     */
598	    private void assignMembershipNumber(Owner owner) {
599	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
600	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
601	    }
