603	    /**
604	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
605	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
606	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
607	     */
608	    private void assignNamesakeCount(Owner owner) {
609	        String firstName = owner.getFirstName();
610	        String lastName = owner.getLastName();
611	        int count = 0;
612	        for (Owner existing : this.clinicService.findAllOwners()) {
613	            if (firstName.equalsIgnoreCase(existing.getFirstName())
614	                && lastName.equalsIgnoreCase(existing.getLastName())) {
615	                count++;
616	            }
617	        }
618	        owner.setNamesakeCount(count);
619	    }
620	
621	    /**
622	     * Assigns the new owner's {@code membershipLevel} on create: a number from 1 to 3 starting at
623	     * 1, plus 1 when an email is present, plus 1 when {@code namesakeCount} is 0, capped at 3.
624	     * Level 4 is reserved for tenure. Runs after {@link #assignNamesakeCount} so that count is
625	     * settled.
626	     */
627	    private void assignMembershipLevel(Owner owner) {
628	        int level = 1;
629	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
630	            level++;
631	        }
632	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
633	            level++;
634	        }
635	        owner.setMembershipLevel(Math.min(level, 3));
636	    }
637	
638	    /**
639	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
640	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
641	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
642	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
643	     * pre-existing owners for that day.
644	     */
645	    private void assignBulkSignupWarning(Owner owner) {
646	        LocalDate registrationDate = owner.getRegistrationDate();
647	        int count = 0;
648	        for (Owner existing : this.clinicService.findAllOwners()) {
649	            if (registrationDate.equals(existing.getRegistrationDate())) {
650	                count++;
651	            }
652	        }
653	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
654	    }
655	
656	    /**
657	     * Assigns the new owner's {@code householdId} when the request opts in with
658	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
659	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
660	     * same way {@link #householdMembers} matches). The household's members and the new owner
661	     * all end up carrying one stable shared identifier: if any existing member already has a
662	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
663	     * and address. Any existing member that is missing the identifier is updated so the whole
664	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
665	     * identifier is assigned.
666	     */
667	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
668	        String householdId = resolveHouseholdId(ownerFieldsDto);
669	        if (householdId == null) {
670	            return;
671	        }
672	        owner.setHouseholdId(householdId);
673	        String lastName = normalizeForComparison(owner.getLastName());
674	        String address = canonicalAddress(owner.getAddress());
675	        for (Owner member : householdMembers(lastName, address)) {
676	            if (!householdId.equals(member.getHouseholdId())) {
677	                member.setHouseholdId(householdId);
678	                this.clinicService.saveOwner(member);
679	            }
680	        }
681	    }
682	
683	    /**
684	     * Resolves, without any mutation, the {@code householdId} a new owner would be assigned, so it
685	     * can feed both the {@code identityKey} duplicate check and the actual {@link #assignHousehold}
686	     * assignment. Returns {@code null} unless the request opts in with {@code sharesHousehold} set to
687	     * {@code true} and at least one existing owner already shares the same normalized last name and
688	     * address; in that case the household's existing stable identifier is reused, or a new one is
689	     * derived from the normalized last name and address when none of the members carries one yet.
690	     */
691	    private String resolveHouseholdId(OwnerFieldsDto ownerFieldsDto) {
692	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
693	            return null;
694	        }
695	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
696	        String address = canonicalAddress(ownerFieldsDto.getAddress());
697	        List<Owner> members = householdMembers(lastName, address);
698	        if (members.isEmpty()) {
699	            return null;
700	        }
701	        return members.stream()
702	            .map(Owner::getHouseholdId)
703	            .filter(id -> id != null && !id.isBlank())
704	            .findFirst()
705	            .orElseGet(() -> newHouseholdId(lastName, address));
706	    }
707	
708	    /**
709	     * Returns every existing owner sharing the given normalized last name and address (compared
710	     * case-insensitively with runs of whitespace collapsed), the members of a household.
711	     */
712	    private List<Owner> householdMembers(String normalizedLastName, String normalizedAddress) {
713	        List<Owner> members = new ArrayList<>();
714	        for (Owner existing : this.clinicService.findAllOwners()) {
715	            if (normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
716	                && normalizedAddress.equals(canonicalAddress(existing.getAddress()))) {
717	                members.add(existing);
718	            }
719	        }
720	        return members;
721	    }
722	
723	    /**
724	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
725	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
726	     * every existing owner already carrying the same identifier. Runs after {@link #assignHousehold}
727	     * so the identifier is settled. Left {@code null} when the owner belongs to no household.
728	     */
729	    private void assignHouseholdMembership(Owner owner) {
730	        String householdId = owner.getHouseholdId();
731	        if (householdId == null || householdId.isBlank()) {
732	            owner.setHouseholdMemberCount(null);
733	            return;
734	        }
735	        int count = 1;
736	        for (Owner existing : this.clinicService.findAllOwners()) {
737	            if (householdId.equals(existing.getHouseholdId())) {
738	                count++;
739	            }
740	        }
741	        owner.setHouseholdMemberCount(count);
742	    }
743	
744	    /**
745	     * Derives a stable household identifier from the normalized last name and address: the first
746	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
747	     * owners in the same household therefore derive the same value regardless of creation order.
748	     */
749	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
750	        try {
751	            byte[] digest = MessageDigest.getInstance("SHA-256")
752	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
753	            StringBuilder hex = new StringBuilder(digest.length * 2);
754	            for (byte b : digest) {
755	                hex.append(String.format("%02x", b));
756	            }
757	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
758	        } catch (NoSuchAlgorithmException ex) {
759	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
760	        }
761	    }
762	}
